@reprlib.recursive_repr()
def __repr__(self) -> str:
    lst = []
    for e in self._md._keys.iter_entries():
        lst.append(f"'{e.key}': {e.value!r}")
    body = ", ".join(lst)
    return f"<{self.__class__.__name__}({body})>

@reprlib.recursive_repr()
def __repr__(self) -> str:
    lst = []
    for e in self._md._keys.iter_entries():
        lst.append(repr(e.value))
    body = ", ".join(lst)
    return f"<{self.__class__.__name__}({body})>"
